// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));

        Reverter rev = new Reverter();

        address badRecipient = address(rev);

        bool ok;
        try c.getFirstWithdrawalBonus(badRecipient) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("no receive");
    }
    receive() external payable {
        revert("no receive");
    }
}
